import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for `key` in a `name=value` per-line config text.

    Rules:
    - The text is split into lines; each line is stripped of surrounding
      whitespace. Blank lines and lines starting with "#" are ignored, as are
      lines with no "=".
    - A line is split at its first "=", so values may themselves contain "=".
      The name and the value are each stripped of surrounding whitespace.
    - `key` is matched exactly (case-sensitive, whole name, not a prefix).
      `key` itself is not stripped.
    - If the key appears more than once, the first occurrence wins.
    - If the key is absent, return "". A key present with nothing after "="
      also yields "".
    - Does not read files; `text` is the only input source.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_basic_lookup() -> None:
    assert config_value("a=1\nb=2\nc=3", "b") == "2"


def test_absent_key_returns_empty_string() -> None:
    assert config_value("a=1\nb=2", "z") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_around_name_and_value_is_stripped() -> None:
    assert config_value("  name  =  some value  \n", "name") == "some value"


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?q=1&r=2", "url") == "http://x/?q=1&r=2"


def test_empty_value_returns_empty_string() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_first_occurrence_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_key_must_match_whole_name() -> None:
    text = "ab=1\na=2\nabc=3"
    assert config_value(text, "a") == "2"
    assert config_value("ab=1", "a") == ""
    assert config_value("a=1", "ab") == ""


def test_key_is_case_sensitive() -> None:
    assert config_value("Key=1", "key") == ""
    assert config_value("Key=1", "Key") == "1"


def test_comments_and_blank_lines_are_ignored() -> None:
    text = "# a=hidden\n\n   \na=shown"
    assert config_value(text, "a") == "shown"
    assert config_value("#a=1", "#a") == ""


def test_lines_without_equals_are_ignored() -> None:
    assert config_value("junk\na=1", "junk") == ""
    assert config_value("junk\na=1", "a") == "1"


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


def test_value_is_not_found_in_other_keys_values() -> None:
    assert config_value("a=b\nb=c", "b") == "c"


@pytest.mark.parametrize(
    ("text", "key", "expected"),
    [
        ("x=1", "x", "1"),
        ("x = 1", "x", "1"),
        ("\n\nx=1\n\n", "x", "1"),
        ("y=1", "x", ""),
    ],
)
def test_parametrized(text: str, key: str, expected: str) -> None:
    assert config_value(text, key) == expected
